package org.jlinalg.cli;

import java.nio.file.*;
import java.util.*;
import org.jlinalg.sequence.LeafCutterPhenotypes;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Actual-JAR comparison driver; no complete LeafCutter workflow admission. */
public final class LeafCutterPhenotypesMatrix {
    private LeafCutterPhenotypesMatrix() { }
    private static Map<String,Object> original(LeafCutterPhenotypes.Row row){return Map.of("id",row.id(),"counts",row.counts().stream().map(c->List.of(c.numerator(),c.denominator())).toList());}
    private static Map<String,Object> decision(LeafCutterPhenotypes.Decision d){var r=new LinkedHashMap<String,Object>();r.put("ordinal",d.ordinal());r.put("id",d.original().id());r.put("disposition",d.disposition().name());r.put("source_ratios",d.sourceRatios());r.put("missing",d.missing());r.put("observed_mean",d.observedMean());r.put("observed_minimum",d.observedMinimum());r.put("observed_maximum",d.observedMaximum());r.put("population_stddev",d.populationStddev());return r;}
    private static Map<String,Object> kept(LeafCutterPhenotypes.Kept d){var r=new LinkedHashMap<String,Object>();r.put("input_ordinal",d.inputOrdinal());r.put("id",d.id());r.put("chromosome",d.chromosome());r.put("start_text",d.startText());r.put("end_text",d.endText());r.put("start",d.start());r.put("imputed_ratios",d.imputedRatios());r.put("standardized",d.standardized());r.put("inverse_normal_scores",d.inverseNormalScores());r.put("observed_mean",d.observedMean());r.put("observed_minimum",d.observedMinimum());r.put("observed_maximum",d.observedMaximum());r.put("scaling_mean",d.scalingMean());r.put("population_stddev",d.populationStddev());return r;}
    private static Map<String,Object> result(LeafCutterPhenotypes.Result d){return Map.of("samples",d.samples(),"original_rows",d.originalRows().stream().map(LeafCutterPhenotypesMatrix::original).toList(),"chromosomes_seen",d.chromosomesSeen(),"decisions",d.decisions().stream().map(LeafCutterPhenotypesMatrix::decision).toList(),"kept",d.kept().stream().map(LeafCutterPhenotypesMatrix::kept).toList(),"sorted_ids",d.sortedForSourceFiles().stream().map(LeafCutterPhenotypes.Kept::id).toList(),"warnings",d.warnings());}
    public static void main(String[] args)throws Exception {
        require(args.length==2,"Need complete literal cases and NEW output directory");Path request=Path.of(args[0]),out=Path.of(args[1]);byte[] raw=NextflowFiles.bytes(request,16777216);var root=object(NextflowParameters.parse(NextflowFiles.utf8(raw),16777216,2000000));require(!Files.exists(out),"Existing native output protected");Files.createDirectory(out);var reports=new ArrayList<Object>();
        for(Object item:list(root.get("cases"))){var c=object(item);String id=text(c.get("id"));require(id.matches("[a-z0-9-]+"),"Unsafe case name");var capacity=object(c.get("limits"));var limits=new LeafCutterPhenotypes.Limits(Math.toIntExact(integer(capacity.get("maximum_samples"),1,1000000)),Math.toIntExact(integer(capacity.get("maximum_input_rows"),1,1000000)),integer(capacity.get("maximum_input_cells"),1,Long.MAX_VALUE),integer(capacity.get("maximum_rank_comparisons"),1,Long.MAX_VALUE));var samples=new ArrayList<String>();for(Object value:list(c.get("samples")))samples.add(text(value));var blacklist=new ArrayList<String>();for(Object value:list(c.get("blacklist")))blacklist.add(text(value));var rows=new ArrayList<LeafCutterPhenotypes.Row>();
            for(Object value:list(c.get("rows"))){var row=object(value);var pairs=new ArrayList<LeafCutterPhenotypes.Counts>();for(Object v:list(row.get("counts"))){var pair=list(v);require(pair.size()==2,"Numerator/denominator pair required");pairs.add(new LeafCutterPhenotypes.Counts(integer(pair.get(0),0,Long.MAX_VALUE),integer(pair.get(1),0,Long.MAX_VALUE)));}rows.add(new LeafCutterPhenotypes.Row(text(row.get("id")),pairs));}
            var computed=LeafCutterPhenotypes.compute(samples,rows,new LeafCutterPhenotypes.Options(blacklist),limits);NextflowFiles.writeJson(out.resolve(id+".json"),result(computed));reports.add(Map.of("id",id,"kept",computed.kept().size(),"rows",rows.size()));
        }
        var invalid=new ArrayList<String>();var counts=List.of(new LeafCutterPhenotypes.Counts(0,10),new LeafCutterPhenotypes.Counts(5,10),new LeafCutterPhenotypes.Counts(10,10));var row=new LeafCutterPhenotypes.Row("chr1:100:200:clu_1_+",counts);var row2=new LeafCutterPhenotypes.Row("chr1:120:200:clu_2_+",counts);var samples=List.of("S3","S1","S2");var options=LeafCutterPhenotypes.Options.sourceDefaults();var limits=LeafCutterPhenotypes.Limits.defaults();
        reject("negative-count",()->new LeafCutterPhenotypes.Counts(-1,10),invalid);reject("count-exceeds-cluster-total",()->new LeafCutterPhenotypes.Counts(11,10),invalid);reject("negative-denominator",()->new LeafCutterPhenotypes.Counts(0,-1),invalid);reject("ragged-sample-family",()->LeafCutterPhenotypes.compute(List.of("S1"),List.of(row),options,limits),invalid);reject("duplicate-sample-header",()->LeafCutterPhenotypes.compute(List.of("S1","S1","S2"),List.of(row),options,limits),invalid);reject("source-header-key-collision",()->LeafCutterPhenotypes.compute(List.of("chrom","S1","S2"),List.of(row),options,limits),invalid);reject("duplicate-intron-ID",()->LeafCutterPhenotypes.compute(samples,List.of(row,row),options,limits),invalid);reject("malformed-intron-ID",()->new LeafCutterPhenotypes.Row("chr1:100:200",counts),invalid);reject("reversed-coordinate",()->new LeafCutterPhenotypes.Row("chr1:200:100:clu_1_+",counts),invalid);reject("unsafe-source-chromosome-filename",()->new LeafCutterPhenotypes.Row("chr1/alt:100:200:clu_1_+",counts),invalid);reject("unpaired-surrogate",()->new LeafCutterPhenotypes.Row("chr1:100:200:clu_\ud800",counts),invalid);reject("sample-capacity",()->LeafCutterPhenotypes.compute(samples,List.of(row),options,new LeafCutterPhenotypes.Limits(2,100,1000,10000)),invalid);reject("row-capacity",()->LeafCutterPhenotypes.compute(samples,List.of(row,row2),options,new LeafCutterPhenotypes.Limits(10,1,1000,10000)),invalid);reject("complete-cell-capacity",()->LeafCutterPhenotypes.compute(samples,List.of(row),options,new LeafCutterPhenotypes.Limits(10,100,2,10000)),invalid);reject("rank-comparison-capacity",()->LeafCutterPhenotypes.compute(samples,List.of(row,row2),options,new LeafCutterPhenotypes.Limits(10,100,1000,1)),invalid);reject("source-no-retained-introns",()->LeafCutterPhenotypes.compute(samples,List.of(),options,limits),invalid);reject("source-all-constant",()->LeafCutterPhenotypes.compute(samples,List.of(new LeafCutterPhenotypes.Row(row.id(),List.of(counts.get(0),counts.get(0),counts.get(0)))),options,limits),invalid);reject("source-all-missing",()->LeafCutterPhenotypes.compute(samples,List.of(new LeafCutterPhenotypes.Row(row.id(),List.of(new LeafCutterPhenotypes.Counts(0,0),new LeafCutterPhenotypes.Counts(0,0),new LeafCutterPhenotypes.Counts(0,0)))),options,limits),invalid);
        require(Arrays.equals(raw,NextflowFiles.bytes(request,16777216)),"Original literal fixture changed during native preprocessing");NextflowFiles.writeJson(out.resolve("COMPLETED.json"),Map.of("status","PASS_NATIVE_LEAFCUTTER_PHENOTYPE_COMPONENT_ONLY","cases",reports,"expected_native_rejections",invalid,"implementation_credit",false,"whole_goal_complete",false));System.out.println("Native LeafCutter phenotype component: "+reports.size()+" cases; "+invalid.size()+" expected rejections");
    }
    @FunctionalInterface private interface Check {Object run()throws Exception;}
    private static void reject(String name,Check check,List<String> errors)throws Exception{boolean rejected=false;try{check.run();}catch(IllegalArgumentException expected){rejected=true;}require(rejected,"Native invalid input unexpectedly admitted: "+name);errors.add(name);}
}
